// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint64 number1,
        uint64 number2,
        uint64 timestamp,
        uint256 basefee,
        bytes32 hash,
        uint64 sequenceNumber,
        bytes32 batcherHash,
        uint256 l1FeeOverhead,
        uint256 l1FeeScalar
    ) public {
        // keep the domain wide; only require the two successive numbers to differ
        // so the rule "number always equals the most recent supplied value" is exercised.
        vm.assume(number1 != number2);
        vm.assume(number2 != 0);

        address depositor = c.DEPOSITOR_ACCOUNT();

        // first call
        vm.prank(depositor);
        c.setL1BlockValues(number1, timestamp, basefee, hash, sequenceNumber, batcherHash, l1FeeOverhead, l1FeeScalar);

        // second call with a different value: number must track the latest supplied value
        vm.prank(depositor);
        c.setL1BlockValues(number2, timestamp, basefee, hash, sequenceNumber, batcherHash, l1FeeOverhead, l1FeeScalar);

        assertTrue(c.number() == number2);
    }
}

